-- pintopets_pet_members: tenant-scoped rows behind /pet-members (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_pet_members (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            user_uuid UUID NOT NULL,
            role VARCHAR(255) NOT NULL,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_pet_members_role_check CHECK (role IN ('owner', 'co_owner', 'carer'))
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_pet_members_namespace ON pintopets_pet_members (namespace_id, id DESC)")
    db.query("CREATE UNIQUE INDEX IF NOT EXISTS uq_pintopets_pet_members_pet_user ON pintopets_pet_members (pet_uuid, user_uuid)")
    db.query("CREATE UNIQUE INDEX IF NOT EXISTS uq_pintopets_pet_members_one_owner ON pintopets_pet_members (pet_uuid) WHERE role = 'owner'")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_pet_members_user ON pintopets_pet_members (namespace_id, user_uuid)")
end
